parameters.jsCode:
const row = $input.first().json;
const internName = `${row.first_name} ${row.last_name}`;
const reminders = [];

if (row.intern_email) {
  reminders.push({
    recipient: row.intern_email,
    kind: 'intern',
    internship_id: row.internship_id,
    employee_id: row.employee_id,
    intern_name: internName
  });
}

if (row.supervisor_email) {
  reminders.push({
    recipient: row.supervisor_email,
    kind: 'supervisor',
    internship_id: row.internship_id,
    employee_id: row.employee_id,
    intern_name: internName
  });
}

return reminders.map((item) => ({ json: item }));

